'use strict';

// Runs the menu-api parser against the real snapshots saved by capture.js.
// Needs the snapshot folders to be present (they are not generated by the tests).

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { buildRecordsFromApi, parseRatingCount } = require('../lib/menu-api');

const SNAP = path.join(__dirname, '..', 'snapshots');
const PISTA = path.join(SNAP, 'rest1239425', '2026-10-26T22-26-32-573Z');
const GOOD_BOWL = path.join(SNAP, 'rest156449', '2026-10-26T22-26-57-956Z');

function load(dir) {
  const meta = JSON.parse(fs.readFileSync(path.join(dir, 'meta.json'), 'utf8'));
  const json = JSON.parse(fs.readFileSync(path.join(dir, 'menu-api-1.json'), 'utf8'));
  return buildRecordsFromApi(json, meta.url, meta.started_at);
}

test('parseRatingCount handles K-suffixed and plain counts', () => {
  assert.deepEqual(parseRatingCount('1.8K+ ratings'), { txt: '1.8K+', count: 1800 });
  assert.deepEqual(parseRatingCount('350 ratings'), { txt: '350', count: 350 });
  assert.deepEqual(parseRatingCount(null), { txt: null, count: null });
});

test('Pista House: all 170 items, 23 sections, status ok', () => {
  const rec = load(PISTA);
  assert.equal(rec.restaurant.name, 'Pista House');
  assert.equal(rec.restaurant.cost_for_two, 500);
  assert.equal(rec.meta.dishes_expected, 170);
  assert.equal(rec.dishes.length, 170);
  assert.equal(rec.meta.sections.length, 23);
  assert.equal(rec.meta.status, 'ok');
});

test('Good Bowl: all 153 items, 19 sections, status ok', () => {
  const rec = load(GOOD_BOWL);
  assert.equal(rec.dishes.length, 153);
  assert.equal(rec.meta.sections.length, 19);
  assert.equal(rec.meta.status, 'ok');
});

test('prices are converted from paise to rupees and match the page', () => {
  const dish = load(PISTA).dishes.find((d) => d.name === 'Chicken Biryani Full');
  assert.equal(dish.price, 458); // page: "Costs: 458 rupees"
  assert.equal(dish.stars, 4.1);
  assert.equal(dish.rating_count, 181); // page: "(181)"
  assert.equal(dish.is_veg, 0);
});

test('a dish with no top-level price takes the lowest variant price', () => {
  const dish = load(PISTA).dishes.find((d) => d.name === 'Murgh Musallam');
  assert.equal(dish.price, 664); // variants: Half 664, Full 825
});

test('unrated dishes have null stars and null count, not zero', () => {
  const rated = load(PISTA).dishes.filter((d) => d.stars != null).length;
  assert.equal(rated, 116);
  const unrated = load(PISTA).dishes.filter((d) => d.stars == null);
  assert.equal(unrated.length, 54);
  assert.ok(unrated.every((d) => d.rating_count == null));
});

test('no duplicate (category, name) pairs reach the database', () => {
  for (const dir of [PISTA, GOOD_BOWL]) {
    const rec = load(dir);
    const keys = new Set(rec.dishes.map((d) => `${d.category}|${d.name}`));
    assert.equal(keys.size, rec.dishes.length);
    assert.equal(rec.meta.note, null);
  }
});
